const { chromium } = require('/home/oliver/.npm/_npx/fd3bca3c548369c0/node_modules/playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 375, height: 800 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('http://127.0.0.1:8123/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);

  const info = await page.evaluate(() => {
    const c = document.querySelector('#line-chart circle.point');
    const r = c.getBoundingClientRect();
    const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
    const top = document.elementFromPoint(cx, cy);
    return {
      rect: { x: r.x, y: r.y, w: r.width, h: r.height },
      scrollY: window.scrollY,
      atPoint: top ? top.tagName + '.' + top.className : null,
      fill: getComputedStyle(c).fill,
    };
  });
  console.log(JSON.stringify(info, null, 2));

  // hover with playwright
  const box = await (await page.$('#line-chart circle.point')).boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2, { steps: 5 });
  await page.waitForTimeout(200);
  console.log('tooltip visible:', await page.$eval('#tooltip', e => e.classList.contains('visible')));
  console.log('tooltip html:', await page.$eval('#tooltip', e => e.innerHTML));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

