const { chromium } = require('/home/oliver/.npm/_npx/fd3bca3c548369c0/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:8123/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);

  // proportionality: bar width must be proportional to value (same scale, zero start)
  const check = async (metric) => {
    await page.selectOption('#metric', metric);
    await page.waitForTimeout(150);
    return page.$$eval('#bar-chart rect.bar', els => els.map(e => ({
      v: parseFloat(e.dataset.value), w: parseFloat(e.getAttribute('width')),
    })));
  };
  for (const metric of ['humaneval_pass_pct', 'tenq_score', 'tenq_tokens']) {
    const bars = await check(metric);
    const k = bars.map(b => b.w / b.v);
    console.log(metric, '-> bars:', bars.length, 'w/v ratios:', k.map(x => x.toFixed(4)).join(' (') + ')', 'consistent:', Math.max(...k) - Math.min(...k) < 0.001);
  }

  // axis starts at 0: first x tick label should be "0"
  const firstTick = await page.$eval('#bar-chart', svg => {
    const texts = [...svg.querySelectorAll('text')].filter(t => t.getAttribute('text-anchor') === 'middle');
    return texts.length ? texts[0].textContent : null;
  });
  console.log('bar chart first x tick:', firstTick);

  // line chart axis titles + value labels present
  const lineInfo = await page.evaluate(() => {
    const svg = document.querySelector('#line-chart');
    const titles = [...svg.querySelectorAll('text.axis-title')].map(t => t.textContent);
    return titles;
  });
  console.log('line chart axis titles:', lineInfo);

  // bar value labels: text nodes in bar chart that contain tok/numbers
  await page.selectOption('#metric', 'humaneval_pass_pct');
  await page.waitForTimeout(150);
  const barLabels = await page.$$eval('#bar-chart text', els => els.map(e => e.textContent));
  console.log('bar chart texts:', barLabels.join(' | '));

  // evidence badges in table
  const badges = await page.$$eval('#results-table .badge', els => els.map(e => e.textContent + ' [' + e.className + ']'));
  console.log('badges:', badges);

  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
EOF
