const { chromium } = require('/home/oliver/.npm/_npx/fd3bca3c548369c0/node_modules/playwright');

(async () => {
  const browser = await chromium.launch();
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 375, height: 800 } });
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  await page.goto('http://127.0.0.1:8123/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);

  const results = {};
  const q = sel => page.$eval(sel, el => el.textContent.trim()).catch(() => null);
  const qa = sel => page.$$eval(sel, els => els.length).catch(() => -1);

  // KPIs
  results.kpi_humaneval = await q('[data-kpi="humaneval"]');
  results.kpi_decode = await q('[data-kpi="decode"]');
  results.kpi_models = await q('[data-kpi="models"]');

  // bar chart
  results.bars = await qa('#bar-chart rect.bar');
  results.bar_attrs = await page.$$eval('#bar-chart rect.bar', els =>
    els.map(e => ({ m: e.dataset.model, v: e.dataset.value, w: parseFloat(e.getAttribute('width')) })));

  // metric switch
  await page.selectOption('#metric', 'tenq_tokens');
  await page.waitForTimeout(200);
  results.bars_tenq_tokens = await page.$$eval('#bar-chart rect.bar', els =>
    els.map(e => ({ m: e.dataset.model, v: e.dataset.value })));

  // line chart
  results.series = await qa('#line-chart path.series');
  results.points = await qa('#line-chart circle.point');
  results.legend = await qa('#line-legend .legend-item');

  // tooltip
  const pt = await page.$('#line-chart circle.point');
  const box = await pt.boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.waitForTimeout(150);
  results.tooltip_visible = await page.$eval('#tooltip', e => e.classList.contains('visible'));
  results.tooltip_text = await q('#tooltip');
  await page.mouse.move(5, 5);
  await page.waitForTimeout(150);
  results.tooltip_hidden_after_leave = !(await page.$eval('#tooltip', e => e.classList.contains('visible')));

  // table
  results.table_rows = await qa('#results-table tbody tr');
  results.header_cells = await page.$$eval('#results-table thead th', els => els.map(e => e.dataset.sort));
  // sort decode_tps desc
  await page.click('th[data-sort="decode_tps"]');
  await page.waitForTimeout(100);
  results.sort_desc_first = await q('#results-table tbody tr:first-child td:nth-child(12)');
  await page.click('th[data-sort="decode_tps"]');
  await page.waitForTimeout(100);
  results.sort_asc_first = await q('#results-table tbody tr:first-child td:nth-child(12)');
  // empty cells last: sort tenq_score asc -> Ornith (32) first, Qwen (—) last? Qwen empty
  await page.click('th[data-sort="tenq_score"]');
  await page.waitForTimeout(100);
  results.empty_last_desc = await page.$$eval('#results-table tbody tr', trs =>
    trs.map(t => t.querySelector('td:nth-child(6)').textContent.trim()));

  // horizontal scroll at 375
  results.hscroll_375 = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);

  // theme toggle
  await page.click('#theme-toggle');
  await page.waitForTimeout(150);
  results.dark_class = await page.evaluate(() => document.documentElement.classList.contains('dark'));
  results.theme_saved = await page.evaluate(() => localStorage.getItem('theme'));
  results.btn_text = await q('#theme-toggle');
  await page.reload({ waitUntil: 'networkidle' });
  results.dark_persists = await page.evaluate(() => document.documentElement.classList.contains('dark'));
  await page.click('#theme-toggle');
  await page.waitForTimeout(100);
  results.light_after_toggle = !(await page.evaluate(() => document.documentElement.classList.contains('dark')));

  // desktop viewport check
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.waitForTimeout(400);
  results.hscroll_1280 = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  results.bars_desktop = await qa('#bar-chart rect.bar');

  console.log(JSON.stringify(results, null, 2));
  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

const { chromium } = require('/home/oliver/.npm/_npx/fd3bca3c548369c0/node_modules/playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 375, height: 800 } });
